from marshmallow import Schema, fields, validate, ValidationError


class SignupSchema(Schema):
    username = fields.Str(
        required=True,
        validate=validate.Regexp(r"^[a-zA-Z0-9]+$", error="Must be alphanumeric"),
    )
    email = fields.Email(required=True)
    plan = fields.Str(
        missing="free",
        validate=validate.OneOf(["free", "pro", "team"]),
    )
    age = fields.Int(
        validate=validate.Range(min=16, max=120),
        required=False,
        allow_none=True,
    )

    class Meta:
        unknown = "exclude"


def validate_signup(data: dict) -> dict:
    """Validate sign-up data, returning cleaned dict with defaults filled.
    Raise ValueError with .messages dict on validation errors."""
    schema = SignupSchema()
    try:
        return schema.load(data)
    except ValidationError as err:
        exc = ValueError("Invalid input")
        exc.messages = err.messages
        raise exc
